-- ======================================== -- V4__Create_Quartz_Schema.sql -- ======================================== -- Description: Quartz Scheduler schema for job management -- Author: System -- Date: 2025-10-29 -- Based on: Quartz 2.3.2+ for PostgreSQL -- ========================================
-- ===== Application Tables =====
-- Table: scheduled_job -- Stores custom job metadata (application-specific) CREATE TABLE IF NOT EXISTS scheduled_job ( id BIGSERIAL PRIMARY KEY, job_name VARCHAR(100) NOT NULL, job_group VARCHAR(100) NOT NULL, job_class VARCHAR(255) NOT NULL, description TEXT, cron_expression VARCHAR(100), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', parameters TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(50), updated_by VARCHAR(50), CONSTRAINT uk_job_name_group UNIQUE (job_name, job_group) );
COMMENT ON TABLE scheduled_job IS 'Custom job metadata'; CREATE INDEX IF NOT EXISTS idx_scheduled_job_status ON scheduled_job (status); CREATE INDEX IF NOT EXISTS idx_scheduled_job_name_group ON scheduled_job (job_name, job_group);
DROP TRIGGER IF EXISTS trg_scheduled_job_set_updated_at ON scheduled_job; CREATE TRIGGER trg_scheduled_job_set_updated_at BEFORE UPDATE ON scheduled_job FOR EACH ROW EXECUTE FUNCTION set_updated_at();
-- Table: job_execution_history -- Stores job execution history and results CREATE TABLE IF NOT EXISTS job_execution_history ( id BIGSERIAL PRIMARY KEY, job_id BIGINT NOT NULL, execution_time TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL, duration_ms BIGINT, result TEXT, error_message TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_job_execution_history_job FOREIGN KEY (job_id) REFERENCES scheduled_job(id) ON DELETE CASCADE );
COMMENT ON TABLE job_execution_history IS 'Job execution history'; CREATE INDEX IF NOT EXISTS idx_job_execution_history_job_id ON job_execution_history (job_id); CREATE INDEX IF NOT EXISTS idx_job_execution_history_execution_time ON job_execution_history (execution_time); CREATE INDEX IF NOT EXISTS idx_job_execution_history_status ON job_execution_history (status);
-- ===== Quartz Internal Tables =====
-- Table: QRTZ_JOB_DETAILS CREATE TABLE IF NOT EXISTS QRTZ_JOB_DETAILS ( SCHED_NAME VARCHAR(120) NOT NULL, JOB_NAME VARCHAR(200) NOT NULL, JOB_GROUP VARCHAR(200) NOT NULL, DESCRIPTION VARCHAR(250) DEFAULT NULL, JOB_CLASS_NAME VARCHAR(250) NOT NULL, IS_DURABLE VARCHAR(1) NOT NULL, IS_NONCONCURRENT VARCHAR(1) NOT NULL, IS_UPDATE_DATA VARCHAR(1) NOT NULL, REQUESTS_RECOVERY VARCHAR(1) NOT NULL, JOB_DATA BYTEA, PRIMARY KEY (SCHED_NAME, JOB_NAME, JOB_GROUP) );
CREATE INDEX IF NOT EXISTS idx_qrtz_j_req_recovery ON QRTZ_JOB_DETAILS (SCHED_NAME, REQUESTS_RECOVERY); CREATE INDEX IF NOT EXISTS idx_qrtz_j_grp ON QRTZ_JOB_DETAILS (SCHED_NAME, JOB_GROUP);
-- Table: QRTZ_TRIGGERS CREATE TABLE IF NOT EXISTS QRTZ_TRIGGERS ( SCHED_NAME VARCHAR(120) NOT NULL, TRIGGER_NAME VARCHAR(200) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, JOB_NAME VARCHAR(200) NOT NULL, JOB_GROUP VARCHAR(200) NOT NULL, DESCRIPTION VARCHAR(250) DEFAULT NULL, NEXT_FIRE_TIME BIGINT DEFAULT NULL, PREV_FIRE_TIME BIGINT DEFAULT NULL, PRIORITY INTEGER DEFAULT NULL, TRIGGER_STATE VARCHAR(16) NOT NULL, TRIGGER_TYPE VARCHAR(8) NOT NULL, START_TIME BIGINT NOT NULL, END_TIME BIGINT DEFAULT NULL, CALENDAR_NAME VARCHAR(200) DEFAULT NULL, MISFIRE_INSTR SMALLINT DEFAULT NULL, JOB_DATA BYTEA, PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP), CONSTRAINT fk_qrtz_t_job_details FOREIGN KEY (SCHED_NAME, JOB_NAME, JOB_GROUP) REFERENCES QRTZ_JOB_DETAILS(SCHED_NAME, JOB_NAME, JOB_GROUP), CONSTRAINT fk_qrtz_t_job_group FOREIGN KEY (SCHED_NAME, JOB_NAME, JOB_GROUP) REFERENCES QRTZ_JOB_DETAILS(SCHED_NAME, JOB_NAME, JOB_GROUP) );
CREATE INDEX IF NOT EXISTS idx_qrtz_t_j ON QRTZ_TRIGGERS (SCHED_NAME, JOB_NAME, JOB_GROUP); CREATE INDEX IF NOT EXISTS idx_qrtz_t_jg ON QRTZ_TRIGGERS (SCHED_NAME, JOB_GROUP); CREATE INDEX IF NOT EXISTS idx_qrtz_t_c ON QRTZ_TRIGGERS (SCHED_NAME, CALENDAR_NAME); CREATE INDEX IF NOT EXISTS idx_qrtz_t_g ON QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_GROUP); CREATE INDEX IF NOT EXISTS idx_qrtz_t_state ON QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_STATE); CREATE INDEX IF NOT EXISTS idx_qrtz_t_n_state ON QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP, TRIGGER_STATE); CREATE INDEX IF NOT EXISTS idx_qrtz_t_n_g_state ON QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_GROUP, TRIGGER_STATE); CREATE INDEX IF NOT EXISTS idx_qrtz_t_next_fire_time ON QRTZ_TRIGGERS (SCHED_NAME, NEXT_FIRE_TIME); CREATE INDEX IF NOT EXISTS idx_qrtz_t_nft_st ON QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_STATE, NEXT_FIRE_TIME); CREATE INDEX IF NOT EXISTS idx_qrtz_t_nft_misfire ON QRTZ_TRIGGERS (SCHED_NAME, MISFIRE_INSTR, NEXT_FIRE_TIME); CREATE INDEX IF NOT EXISTS idx_qrtz_t_nft_st_misfire ON QRTZ_TRIGGERS (SCHED_NAME, MISFIRE_INSTR, NEXT_FIRE_TIME, TRIGGER_STATE); CREATE INDEX IF NOT EXISTS idx_qrtz_t_nft_st_misfire_grp ON QRTZ_TRIGGERS (SCHED_NAME, MISFIRE_INSTR, NEXT_FIRE_TIME, TRIGGER_GROUP, TRIGGER_STATE);
-- Table: QRTZ_SIMPLE_TRIGGERS CREATE TABLE IF NOT EXISTS QRTZ_SIMPLE_TRIGGERS ( SCHED_NAME VARCHAR(120) NOT NULL, TRIGGER_NAME VARCHAR(200) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, REPEAT_COUNT BIGINT NOT NULL, REPEAT_INTERVAL BIGINT NOT NULL, TIMES_TRIGGERED BIGINT NOT NULL, PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP), CONSTRAINT fk_qrtz_st_triggers FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) );
-- Table: QRTZ_CRON_TRIGGERS CREATE TABLE IF NOT EXISTS QRTZ_CRON_TRIGGERS ( SCHED_NAME VARCHAR(120) NOT NULL, TRIGGER_NAME VARCHAR(200) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, CRON_EXPRESSION VARCHAR(120) NOT NULL, TIME_ZONE_ID VARCHAR(80), PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP), CONSTRAINT fk_qrtz_ct_triggers FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) );
-- Table: QRTZ_SIMPROP_TRIGGERS CREATE TABLE IF NOT EXISTS QRTZ_SIMPROP_TRIGGERS ( SCHED_NAME VARCHAR(120) NOT NULL, TRIGGER_NAME VARCHAR(200) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, STR_PROP_1 VARCHAR(512) DEFAULT NULL, STR_PROP_2 VARCHAR(512) DEFAULT NULL, STR_PROP_3 VARCHAR(512) DEFAULT NULL, INT_PROP_1 INT DEFAULT NULL, INT_PROP_2 INT DEFAULT NULL, LONG_PROP_1 BIGINT DEFAULT NULL, LONG_PROP_2 BIGINT DEFAULT NULL, DEC_PROP_1 DECIMAL(13,4) DEFAULT NULL, DEC_PROP_2 DECIMAL(13,4) DEFAULT NULL, BOOL_PROP_1 VARCHAR(1) DEFAULT NULL, BOOL_PROP_2 VARCHAR(1) DEFAULT NULL, PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP), CONSTRAINT fk_qrtz_spt_triggers FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) );
-- Table: QRTZ_BLOB_TRIGGERS CREATE TABLE IF NOT EXISTS QRTZ_BLOB_TRIGGERS ( SCHED_NAME VARCHAR(120) NOT NULL, TRIGGER_NAME VARCHAR(200) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, BLOB_DATA BYTEA, PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP), CONSTRAINT fk_qrtz_bt_triggers FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP) );
-- Table: QRTZ_CALENDARS CREATE TABLE IF NOT EXISTS QRTZ_CALENDARS ( SCHED_NAME VARCHAR(120) NOT NULL, CALENDAR_NAME VARCHAR(200) NOT NULL, CALENDAR BYTEA NOT NULL, PRIMARY KEY (SCHED_NAME, CALENDAR_NAME) );
-- Table: QRTZ_PAUSED_TRIGGER_GRPS CREATE TABLE IF NOT EXISTS QRTZ_PAUSED_TRIGGER_GRPS ( SCHED_NAME VARCHAR(120) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, PRIMARY KEY (SCHED_NAME, TRIGGER_GROUP) );
-- Table: QRTZ_FIRED_TRIGGERS CREATE TABLE IF NOT EXISTS QRTZ_FIRED_TRIGGERS ( SCHED_NAME VARCHAR(120) NOT NULL, ENTRY_ID VARCHAR(95) NOT NULL, TRIGGER_NAME VARCHAR(200) NOT NULL, TRIGGER_GROUP VARCHAR(200) NOT NULL, INSTANCE_NAME VARCHAR(200) NOT NULL, FIRED_TIME BIGINT NOT NULL, SCHED_TIME BIGINT NOT NULL, PRIORITY INTEGER NOT NULL, STATE VARCHAR(16) NOT NULL, JOB_NAME VARCHAR(200) DEFAULT NULL, JOB_GROUP VARCHAR(200) DEFAULT NULL, IS_NONCONCURRENT VARCHAR(1) DEFAULT NULL, REQUESTS_RECOVERY VARCHAR(1) DEFAULT NULL, PRIMARY KEY (SCHED_NAME, ENTRY_ID) );
CREATE INDEX IF NOT EXISTS idx_qrtz_ft_trig_inst_name ON QRTZ_FIRED_TRIGGERS (SCHED_NAME, INSTANCE_NAME); CREATE INDEX IF NOT EXISTS idx_qrtz_ft_inst_job_req_rcvry ON QRTZ_FIRED_TRIGGERS (SCHED_NAME, INSTANCE_NAME, REQUESTS_RECOVERY); CREATE INDEX IF NOT EXISTS idx_qrtz_ft_j_g ON QRTZ_FIRED_TRIGGERS (SCHED_NAME, JOB_NAME, JOB_GROUP); CREATE INDEX IF NOT EXISTS idx_qrtz_ft_jg ON QRTZ_FIRED_TRIGGERS (SCHED_NAME, JOB_GROUP); CREATE INDEX IF NOT EXISTS idx_qrtz_ft_t_g ON QRTZ_FIRED_TRIGGERS (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP); CREATE INDEX IF NOT EXISTS idx_qrtz_ft_tg ON QRTZ_FIRED_TRIGGERS (SCHED_NAME, TRIGGER_GROUP);
-- Table: QRTZ_SCHEDULER_STATE CREATE TABLE IF NOT EXISTS QRTZ_SCHEDULER_STATE ( SCHED_NAME VARCHAR(120) NOT NULL, INSTANCE_NAME VARCHAR(200) NOT NULL, LAST_CHECKIN_TIME BIGINT NOT NULL, CHECKIN_INTERVAL BIGINT NOT NULL, PRIMARY KEY (SCHED_NAME, INSTANCE_NAME) );
-- Table: QRTZ_LOCKS CREATE TABLE IF NOT EXISTS QRTZ_LOCKS ( SCHED_NAME VARCHAR(120) NOT NULL, LOCK_NAME VARCHAR(40) NOT NULL, PRIMARY KEY (SCHED_NAME, LOCK_NAME) );

